#include <iostream>
#include <bitset>
#include <stdexcept>

int main() {
    constexpr std::size_t N = 8;
    std::bitset<N> b1; // initially all 0s: 00000000

    b1.set(1); // set bit 1
    b1.set(3); // set bit 3
    b1.set(7); // set bit 7 -> 10001010

    std::cout << "b1: " << b1.to_string() << "\n";
    std::cout << "size: " << b1.size() << ", count: " << b1.count() << "\n";
    std::cout << "any: " << std::boolalpha << b1.any() << ", all: " << b1.all() << "\n";

    b1.flip(1); // turn off bit 1 -> 10001000
    std::cout << "after flip(1): " << b1.to_string() << "\n";

    // Range-checked query using test()
    try {
        std::cout << "bit 3 is: " << b1.test(3) << "\n";
        b1.test(10); // out of range: throws std::out_of_range
    } catch (const std::out_of_range& e) {
        std::cout << "caught out_of_range as expected\n";
    }

    // Bitwise AND operation
    std::bitset<N> b2("00001111");
    std::bitset<N> b_and = b1 & b2;
    std::cout << "b1 & b2: " << b_and.to_string() << " (ulong: " << b_and.to_ulong() << ")\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <list>
#include <deque>
#include <algorithm>

int main() {
    // 1. vector demonstration: front, back, size
    std::vector<int> v = {10, 20, 30};
    v.push_back(40);
    std::cout << "vector front: " << v.front() << ", back: " << v.back() << "\n";
    std::cout << "vector size: " << v.size() << "\n";

    // 2. list demonstration: push_front and splice
    std::list<int> l1 = {1, 3, 5};
    std::list<int> l2 = {2, 4};
    l1.push_front(0); // l1 becomes: 0 1 3 5

    // Splice all nodes of l2 into l1 right before element 3
    auto it = std::find(l1.begin(), l1.end(), 3);
    l1.splice(it, l2); // l1 is now: 0 1 2 4 3 5; l2 is now empty

    std::cout << "list after splice: ";
    for (int n : l1) {
        std::cout << n << " ";
    }
    std::cout << "\n";

    // 3. deque demonstration: push_front and push_back
    std::deque<int> d = {100, 200};
    d.push_front(50);
    d.push_back(300);
    std::cout << "deque front: " << d.front() << ", back: " << d.back() << "\n";

    return 0;
}
